#ifndef ROMFS_H
#define ROMFS_H

#include <stddef.h>

typedef struct
{
    const char *name;            /* base name, e.g. "ca.crt" */
    const unsigned char *data;
    size_t len;
} romfs_file_t;

/* Generated by CMake (romfs_data.c); terminated by { NULL, NULL, 0 }. */
extern const romfs_file_t romfs_files[];

#endif /* ROMFS_H */
